import{_ as n,l as s,o as e,c as i,v as t,p as l,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"瞬态执行对照","description":"","frontmatter":{"title":"瞬态执行对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/transient-exec.md","filePath":"cs/transient-exec.md","lastUpdated":1789023840000}'),h={name:"cs/transient-exec.md"};function E(_,a,A,m,B,f){const o=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="瞬态执行对照" tabindex="-1">瞬态执行对照 <a class="header-anchor" href="#瞬态执行对照" aria-label="Permalink to &quot;瞬态执行对照&quot;">​</a></h1><div class="epigraph"><p>预测执行可以在架构状态回滚之后，仍在缓存与缓冲里留下可测差异；隔离规格若只写寄存器与页表，会漏掉这一层。</p><footer>—— 据 Kocher 等与 Lipp 等对瞬态执行的公开叙述；Anderson 对侧信道扩展威胁模型</footer></div><p><a href="/cs/side-channel">上一课</a>把时间、缓存、功耗标进模型。本课不重列计时。缺口是微结构：<a href="/cs/ooo-rob">乱序</a> 与<a href="/cs/control-hazard-predict">分支预测</a> 会让指令在提交前执行，失败路径被丢弃，但缓存占用还在。对照的是机制与防御（隔离、刷新、栅栏、关预测），不是可运行的探测程序。TLS 握手下一课回到协议。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>侧信道课留下「非规格输出」。瞬态执行：错误预测或故障路径上的加载仍会填缓存，架构寄存器随后像没发生。跨特权、跨进程的机密可能被编码进命中/未命中。缺口是<strong>把组成课的预测器接到威胁模型</strong>，并声明本栏只讲机制与缓解，不提供复现步骤。</p><p><span class="marginnote">Meltdown 式故障抑制与 Spectre 式预测是两条公开叙述。防御包括内核页隔离、微码、序列化、分区缓存。没有一种栅栏取消全部预测收益。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计：敏感代码常时间、不按秘密分支、不按秘密索引缓存。系统：地址空间隔离加强、共享页谨慎、SMT 共核当作同一信任域或关掉。规格：把「架构上看不见」改成「微结构也要预算」。本课不给测量代码。</p>',8)),(e(),l(p,null,{default:r(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPEC%5B%22%E9%A2%84%E6%B5%8B%20%2F%20%E6%95%85%E9%9A%9C%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20ARCH%5B%22%E6%9E%B6%E6%9E%84%E7%8A%B6%E6%80%81%E5%9B%9E%E6%BB%9A%22%5D%0A%20%20SPEC%20--%3E%20UARCH%5B%22%E7%BC%93%E5%AD%98%E7%AD%89%E4%BB%8D%E5%8F%98%E5%8C%96%22%5D%0A%20%20UARCH%20--%3E%20DEF%5B%22%E9%9A%94%E7%A6%BB%20%2F%20%E6%A0%85%E6%A0%8F%20%2F%20%E5%88%B7%E6%96%B0%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>瞬态执行让 CIA 的 C 在「页表已隔离」时仍可能失败。引用监视器看不到缓存。后课 TLS 保护的是链路上的字节，不自动保护同机微结构。组成课的性能机制在此变成安全边界。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把每一次公开变体的名字列成考试。网络上如何协商密钥与证书，下一课 TLS 握手。</p><p>后课默认：侧信道含瞬态执行。会话保密从握手开始在链路上收口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>瞬态执行把预测器变成泄露面。</li><li>防御是隔离与限制推测，代价是性能。</li><li>TLS 握手下一课。</li><li>出处：公开的 Spectre/Meltdown 叙述；Kocher 计时一线；Anderson。</li></ul>',7))])}const S=n(h,[["render",E]]);export{T as __pageData,S as default};
